<template><view class="wish-page"><k-topbar :title="wish?.status==='completed'?'心愿已完成':'心愿订单'" back :fab="false"/>
    <k-subscribe scenes="wish" label="订阅心愿进展提醒" />
  <view v-if="wish" class="w-body" :class="{'wo-with-draft':tab==='chat'&&chatImages.length}"><view class="wo-status" :class="{'wo-status--done':wish.status==='completed'}"><view class="w-between"><view><text class="wo-status__label">{{statusText(wish.status)}}</text><text class="wo-status__copy">{{statusCopy}}</text></view><view class="wo-status__icon"><k-icon :name="wish.status==='completed'?'check':'heart-handshake'" :size="29" :color="wish.status==='completed'?'#102c46':'#e7f58a'"/></view></view><text class="wo-number">心愿编号 #{{wish.wishId}} · {{wish.isOwner?'我发布的':'我帮助的'}}</text></view>
    <view class="wo-find"><text>一对一互助 · 双方都可查看此订单</text><button class="w-link" @click="go(route('mine')+'?role='+(wish.isOwner?'publisher':'helper'))">{{wish.isOwner?'我发布的':'我帮助的'}} →</button></view>
    <view class="w-card wo-summary"><image v-if="wish.images.length" :src="absUrl(wish.images[0])" mode="aspectFill"/><view class="w-grow"><text class="wo-summary__title">{{wish.title}}</text><text class="w-caption">{{wish.targetCity}} → {{wish.originCity}}</text><view class="w-between"><text class="w-muted">{{wish.mode==='free'?'免费互助':'展示价'}}</text><text class="wo-summary__price">¥{{money(wish.amountFen)}}</text></view></view></view>
    <button v-if="['accepted','submitted','disputed'].includes(wish.status)" class="w-secondary wo-mediation" :disabled="busy" @click="wish.status==='disputed' ? tab='progress' : openSheet('dispute')"><k-icon name="scale" :size="18" color="#102c46"/><text>{{wish.status==='disputed'?'查看调解进度':'纠纷调解'}}</text></button>
    <view class="wo-tabs"><view :class="{on:tab==='progress'}" @click="tab='progress'">订单进度</view><view v-if="wish.helperId" :class="{on:tab==='chat'}" @click="tab='chat';loadMessages()">订单沟通</view><view :class="{on:tab==='fees'}" @click="tab='fees'">{{wish.status==='completed'?'完成结算':'费用明细'}}</view></view>
    <template v-if="tab==='progress'">
      <view class="w-card"><text class="w-heading">这次的约定</text><text class="w-copy wo-description">{{wish.description}}</text><view class="w-field"><k-icon name="calendar-days" :size="17" color="#718095"/><text class="w-grow">期望完成</text><text>{{String(wish.deadline).slice(0,10)}}</text></view><view class="w-field"><k-icon name="package" :size="17" color="#718095"/><text class="w-grow">交付方式</text><text>{{deliveryText(wish.delivery)}}</text></view><view class="w-field"><k-icon name="user" :size="17" color="#718095"/><text class="w-grow">{{wish.isOwner?'帮忙的朋友':'心愿发布者'}}</text><text>{{wish.isOwner?(wish.helperName||'等待接单'):wish.publisherName}}</text></view></view>
      <view v-if="wish.delivery==='express'&&wish.helperId" class="w-card wo-shipping">
        <view class="w-between"><text class="w-heading">快递信息</text><button v-if="canEditTracking" class="w-link" @click="openTracking">{{wish.trackingNo?'修改物流':'填写快递单号'}}</button></view>
        <template v-if="wish.trackingNo"><text class="wo-courier">{{wish.courier}}</text><view class="w-between"><text class="wo-tracking">{{wish.trackingNo}}</text><button class="w-link" @click="copyTracking">复制单号</button></view></template>
        <text v-else class="w-caption">{{wish.isHelper?'寄出后填写快递公司和单号，发布者即可查看。':'等待接单者填写快递公司和单号。'}}</text>
      </view>
      <view v-if="wish.proof?.length" class="w-card"><view class="w-between"><text class="w-heading">交付凭证</text><text class="w-tag">等待被看见的心意</text></view><view class="wo-proofs"><image v-for="src in wish.proof" :key="src" :src="absUrl(src)" mode="aspectFill" @click="preview(src)"/></view><text class="w-copy">{{wish.deliveryNote}}</text></view>
      <view v-if="wish.auditNote" class="w-tip"><k-icon name="info" :size="18" color="#3166f5"/><text>平台说明：{{wish.auditNote}}</text></view><view v-if="wish.dispute" class="w-tip w-section"><text>争议说明：{{wish.dispute}}</text></view>
      <view v-if="wish.status==='completed'" class="w-card"><view class="w-between"><text class="w-heading">为这份善意，留个回响</text><k-icon name="heart" :size="21" color="#3166f5"/></view><template v-if="wish.rating"><text class="wo-stars">{{'★'.repeat(wish.rating)}}{{'☆'.repeat(5-wish.rating)}}</text><text class="w-copy">{{wish.review||'感谢这次的帮忙。'}}</text></template><template v-else-if="wish.isOwner"><view class="wo-star-picker"><text v-for="n in 5" :key="n" :class="{on:n<=rating}" @click="rating=n">★</text></view><textarea v-model="review" class="w-input w-area" maxlength="500" placeholder="分享这次互助体验（选填）"/><button class="w-primary w-section" :disabled="busy||!rating" @click="act('review',{rating,note:review})">提交评价</button></template><text v-else class="w-caption">等待发布者留下评价。</text></view>
      <button v-if="wish.isOwner&&['pending_payment','reviewing','open','refund_failed'].includes(wish.status)" class="w-link" :disabled="busy" @click="cancel">{{wish.status==='refund_failed'?'重新申请退款':'取消心愿'}}</button>
    </template>
    <template v-if="tab==='chat'"><view class="w-tip"><k-icon name="shield-check" :size="17" color="#3166f5"/><text>沟通规格、运费和寄送信息。涉及新增食品、烟酒或内容与原约定不符，请申请平台介入重新核实。平台不会索取支付密码。</text></view><button v-if="hasOlder" class="w-link wo-older" @click="loadMessages(true)">加载更早的消息</button><text v-if="chatError" class="w-caption">{{chatError}}</text><view class="wo-chat"><view v-for="m in messages" :key="m.messageId" class="wo-message" :class="{mine:!!m.mine}"><text class="wo-message__meta">{{m.mine?'我':m.nickname}} · {{String(m.createTime).slice(5,16)}}</text><text v-if="m.content" class="wo-message__bubble">{{m.content}}</text><view v-if="m.images?.length" class="wo-message__images"><image v-for="(src,i) in m.images" :key="i" :src="absUrl(src)" mode="aspectFill" @click="previewMessage(m,i)"/></view></view><view v-if="!messages.length&&!chatError" class="w-state"><k-icon name="message-circle" :size="34" color="#a0b2c8"/><text class="w-muted">打个招呼，确认这次心愿的细节吧。</text></view></view></template>
    <template v-if="tab==='fees'"><view v-if="wish.status==='completed'" class="wo-settled"><view class="wo-settled__icon"><k-icon name="check" :size="32" color="#102c46"/></view><text class="w-heading">心愿完成，善意抵达</text><text class="w-caption">{{wish.mode==='free'?'这份帮助无价，平台不收取任何费用。':'本次费用已核算，结算进度如下。'}}</text><text class="wo-settled__amount">¥{{money(wish.netFen)}}</text><text class="w-muted">{{wish.mode==='free'?'免费互助':'服务者净结算金额'}}</text></view><w-fees :value="wish" :free="wish.mode==='free'" :settled="wish.status==='completed'"/><view v-if="wish.status==='completed'&&wish.mode==='paid'" class="w-card w-section"><view class="w-between"><text class="w-heading">打款进度</text><text class="w-tag">{{wish.payoutStatus==='paid'?'平台已登记打款':'待平台打款'}}</text></view><text class="w-caption">{{wish.payoutStatus==='paid'?'打款凭证号：'+wish.payoutReceipt:'平台核实服务者的收款资料后打款。费用核算完成不代表款项已到账。'}}</text><button v-if="wish.isHelper&&wish.payoutStatus!=='paid'" class="w-link" @click="go(route('credential')+'?type=payout')">提交 / 查看收款资料 →</button></view><button class="w-link w-section" @click="go(route('rules'))">查看费用与品类规则</button></template>
    <view v-if="tab==='chat'" class="w-bottom wo-compose">
      <template v-if="canChat"><view v-if="chatImages.length" class="wo-drafts"><view v-for="(pic,i) in chatImages" :key="pic.imageId" class="wo-draft"><image :src="pic.local" mode="aspectFill" @click="previewDraft(i)"/><button :disabled="sending||chatUploading" @click="chatImages.splice(i,1)">移除</button></view></view>
      <text v-if="chatUploading" class="w-caption">图片上传中，请稍候…</text>
      <view class="wo-compose__row"><button class="wo-add" :disabled="sending||chatUploading||chatImages.length>=3" @click="addChatImages"><k-icon name="image" :size="20" color="#3166f5"/><text>图片</text></button><input v-model="message" :disabled="sending" :adjust-position="true" :cursor-spacing="28" placeholder="聊聊心愿的细节…" maxlength="1000" confirm-type="send" @confirm="send"/><button class="w-primary" :disabled="sending||chatUploading||(!message.trim()&&!chatImages.length)" @click="send">{{sending?'发送中':'发送'}}</button></view></template><text v-else class="w-caption">当前订单已关闭，可查看历史沟通。</text>
    </view>
    <view v-else class="w-bottom"><button v-if="wish.isOwner&&wish.status==='pending_payment'" class="w-primary" :disabled="busy" @click="pay">继续支付 ¥{{money(wish.amountFen)}}</button><button v-else-if="wish.isHelper&&wish.status==='accepted'" class="w-primary w-primary--lime" :disabled="busy" @click="openSheet('deliver')">提交完成凭证<k-icon name="arrow-right" :size="21" color="#102c46"/></button><button v-else-if="wish.isOwner&&wish.status==='submitted'" class="w-primary w-primary--lime" :disabled="busy" @click="complete">确认完成<k-icon name="check" :size="21" color="#102c46"/></button><button v-else-if="wish.status==='completed'&&tab!=='fees'" class="w-primary" @click="tab='fees'">查看完成结算<k-icon name="arrow-right" :size="21" color="#e7f58a"/></button><button v-else class="w-primary" :disabled="busy" @click="load">刷新进度<k-icon name="refresh-cw" :size="19" color="#e7f58a"/></button></view>
    <view v-if="trackingOpen" class="w-mask" @click="!busy&&(trackingOpen=false)"><view class="w-sheet" @click.stop><view class="w-between"><text class="w-heading">填写快递信息</text><button class="w-link" :disabled="busy" @click="trackingOpen=false">关闭</button></view><text class="w-caption">保存后双方可查看；完成约定后仍需提交交付凭证。</text><text class="wo-input-label">快递公司</text><input v-model="courier" class="w-input" placeholder="例如：顺丰速运" maxlength="60" :adjust-position="true" :cursor-spacing="28"/><text class="wo-input-label">快递单号</text><input v-model="trackingNo" class="w-input" placeholder="输入或粘贴快递单号" maxlength="80" :adjust-position="true" :cursor-spacing="28"/><button class="w-primary w-section" :disabled="busy||!courier.trim()||!trackingNo.trim()" @click="saveTracking">{{busy?'保存中…':'保存物流信息'}}</button></view></view>
    <view v-if="sheet" class="w-mask" @click="sheet='' "><view class="w-sheet" @click.stop><view class="w-between"><text class="w-heading">{{sheet==='deliver'?'提交完成凭证':'申请平台介入'}}</text><button class="w-link" @click="sheet=''">关闭</button></view><text class="w-caption">{{sheet==='deliver'?'请上传1–6张真实交付照片（必填，单张不超过20MB），并填写5–500字完成说明。发布者确认后才会结算。':'说明问题和希望的处理方式。平台处理期间暂停完成结算。'}}</text><w-photos v-if="sheet==='deliver'" v-model="proof" @busy="uploading=$event"/><textarea v-model="note" :fixed="true" :adjust-position="true" :cursor-spacing="24" class="w-input w-area w-section" maxlength="500" placeholder="请填写至少5个字的说明"/><button class="w-primary w-section" :disabled="busy||uploading||note.trim().length<5||(sheet==='deliver'&&!proof.length)" @click="act(sheet,{note,images:proof})">{{busy?'提交中…':'确认提交'}}</button></view></view>
  </view><view v-else class="w-state"><text>{{error||'正在加载订单…'}}</text><button v-if="error" class="w-secondary" @click="load">重新加载</button></view>
</view></template>
<script setup>
import { computed,ref } from 'vue'
import { onLoad,onShow,onHide,onUnload } from '@dcloudio/uni-app'
import { wishDetail,wishAction,wishMessages,wishSend } from '@/common/wish-api.js'
import { payFlow } from '@/common/pay-flow.js'
import { absUrl,uploadTo } from '@/common/upload.js'
import { getToken } from '@/common/request.js'
import { chooseWishPhotos,PHOTO_MAX_BYTES } from './photo-upload.js'
import { go,toast } from '@/common/screen.js'
import { confirm } from '@/common/ui.js'
import { money,route,statusText,deliveryText,requestKey } from './wish.js'
import WFees from './components/w-fees.vue'
import WPhotos from './components/w-photos.vue'
const id=ref(0),wish=ref(null),error=ref(''),busy=ref(false),tab=ref('progress'),sheet=ref(''),note=ref(''),proof=ref([]),uploading=ref(false),rating=ref(0),review=ref(''),messages=ref([]),message=ref(''),sending=ref(false),chatError=ref(''),hasOlder=ref(false)
const chatImages=ref([]),chatUploading=ref(false),trackingOpen=ref(false),courier=ref(''),trackingNo=ref('')
const canEditTracking=computed(()=>wish.value?.isHelper&&['accepted','submitted'].includes(wish.value?.status))
const canChat=computed(()=>!!wish.value?.helperId&&['accepted','submitted','disputed','completed'].includes(wish.value?.status))
let timer=null,chatBusy=false,sendAttempt=null,visible=false,loadVersion=0,sessionToken='',disposed=false
function currentSession(token){return !disposed&&token===getToken()}
function openTracking(){courier.value=wish.value.courier||'';trackingNo.value=wish.value.trackingNo||'';trackingOpen.value=true}
async function saveTracking(){const number=trackingNo.value.replace(/\s+/g,'');if(!/^[A-Za-z0-9-]{6,80}$/.test(number)){toast('请填写6至80位快递单号');return}await act('tracking',{courier:courier.value.trim(),trackingNo:number})}
function copyTracking(){uni.setClipboardData({data:wish.value.trackingNo})}
function previewDraft(index){uni.previewImage({current:chatImages.value[index].local,urls:chatImages.value.map(p=>p.local)})}
async function previewMessage(m,index){
  const token=getToken()
  try{const rows=(await wishMessages(id.value,Number(m.messageId)+1)).data;if(!currentSession(token))return;const fresh=rows.find(x=>x.messageId===m.messageId);if(!fresh?.images?.length)throw new Error('图片暂不可用，请刷新消息');m.images=fresh.images;uni.previewImage({current:absUrl(fresh.images[index]||fresh.images[0]),urls:fresh.images.map(absUrl)})}catch(e){if(currentSession(token))toast(e.message||'图片加载失败')}
}
async function addChatImages(){
  if(chatUploading.value||sending.value||!canChat.value||chatImages.value.length>=3)return
  const token=getToken();chatUploading.value=true
  try{const picked=await chooseWishPhotos(3-chatImages.value.length);for(const file of picked.slice(0,3-chatImages.value.length)){if(!currentSession(token))return;if(file.size>PHOTO_MAX_BYTES)throw new Error('单张图片不能超过20MB');const data=(await uploadTo(`/app/wishes/${id.value}/message-images`,file.path)).data;if(!currentSession(token))return;if(!data?.imageId||!data?.url)throw new Error('图片上传失败，请重试');chatImages.value.push({imageId:data.imageId,local:file.path})}}catch(e){if(currentSession(token))toast(e.message||'图片上传失败')}finally{chatUploading.value=false}
}
const statusCopy=computed(()=>({pending_payment:'支付后进入内容审核，30分钟内可支付。',reviewing:'正在审核心愿内容，通过后在广场展示。',open:'心愿已出发，等一位远方的朋友回应。',accepted:wish.value?.isHelper?'你已接下这份心愿，请完成约定后提交凭证。':'你的心愿已被接单，可与帮忙的朋友沟通。',submitted:'服务者已提交凭证，请发布者核实后确认。',completed:'谢谢你，让城市之间多了一点温暖。',disputed:'平台正在核实情况，结算已暂停。',refunding:'已申请原路退款，以支付渠道处理结果为准。',refund_failed:'退款未完成，可重试或联系平台处理。',cancelled:'心愿已取消，有偿订单以支付渠道退款记录为准。'}[wish.value?.status]||''))
async function load() {
  if (!id.value) return
  const version = ++loadVersion
  try {
    error.value = ''
    const data = (await wishDetail(id.value)).data
    if (version !== loadVersion) return
    if (!data.isOwner && !data.isHelper) throw new Error('仅订单双方可查看此订单')
    wish.value = data
  } catch (failure) {
    if (version !== loadVersion) return
    wish.value = null
    error.value = failure.message || '加载失败'
  }
}
async function act(action,body={}){if(busy.value)return;busy.value=true;loadVersion++;try{const data=(await wishAction(id.value,action,body)).data;loadVersion++;wish.value=data;error.value='';sheet.value='';if(action==='tracking')trackingOpen.value=false;toast(action==='review'?'评价已提交':action==='tracking'?'物流信息已保存':'进度已更新');if(action==='complete')tab.value='fees'}catch(e){toast(e.message||'操作失败，请重试')}finally{busy.value=false}}
function openSheet(kind){sheet.value=kind;note.value='';proof.value=[]}
async function cancel(){if(await confirm('取消这份心愿？',wish.value.mode==='free'?'取消后将不再展示。':'尚未接单的心愿可取消，已支付金额全额原路退回。'))await act('cancel')}
async function complete(){if(await confirm('确认已经收到约定的交付？',wish.value.mode==='free'?'确认后心愿完成，平台不收取费用。':`确认后将扣除 ¥${money(wish.value.feeFen)} 手续费，服务者结算 ¥${money(wish.value.netFen)}。`))await act('complete')}
async function pay(){if(busy.value)return;busy.value=true;try{const r=await payFlow(wish.value.payNo);if(r.status==='unknown')toast('支付结果确认中，请稍后刷新');await load()}catch(e){toast(e.message||'支付失败')}finally{busy.value=false}}
function preview(src){uni.previewImage({current:absUrl(src),urls:wish.value.proof.map(absUrl)})}
async function loadMessages(older=false){if(chatBusy||!wish.value?.helperId)return;chatBusy=true;const token=getToken();try{const d=(await wishMessages(id.value,older?messages.value[0]?.messageId||0:0)).data;if(!currentSession(token))return;const byId=new Map(messages.value.map(x=>[x.messageId,x]));for(const m of d)byId.set(m.messageId,m);messages.value=[...byId.values()].sort((a,b)=>a.messageId-b.messageId);if(older||messages.value.length<=50)hasOlder.value=d.length===50;chatError.value=''}catch(e){if(currentSession(token))chatError.value=e.message||'消息加载失败'}finally{chatBusy=false}}
async function send(){
  const content=message.value.trim(),imageIds=chatImages.value.map(p=>p.imageId),token=getToken()
  if(sending.value||chatUploading.value||!canChat.value||(!content&&!imageIds.length))return
  sending.value=true
  if(!sendAttempt||sendAttempt.content!==content||JSON.stringify(sendAttempt.imageIds)!==JSON.stringify(imageIds))sendAttempt={requestKey:requestKey(),content,imageIds}
  try{await wishSend(id.value,sendAttempt);if(!currentSession(token))return;message.value='';chatImages.value=[];sendAttempt=null;await loadMessages();uni.pageScrollTo({scrollTop:100000,duration:200})}catch(e){if(currentSession(token))toast(e.message||'发送失败，请重试')}finally{sending.value=false}
}
function stop(){visible=false;if(timer)clearInterval(timer);timer=null}
onLoad(q=>id.value=Number(q.id));onShow(async()=>{stop();visible=true;const token=getToken();if(sessionToken!==token){sessionToken=token;messages.value=[];chatImages.value=[];message.value='';sendAttempt=null;wish.value=null;trackingOpen.value=false;sheet.value=''}await load();if(!visible)return;if(tab.value==='chat')loadMessages();timer=setInterval(()=>{if(tab.value==='chat')loadMessages()},6000)});onHide(stop);onUnload(()=>{disposed=true;loadVersion++;stop()})
</script>
